// signed cookies (cookies secret: :secret_key, format :hmac): written by the compiler
fn axum_dsl_cookie_key() -> &'static [u8] {
    settings().secret_key.as_bytes()
}

fn axum_dsl_cookie_mac(secret: &[u8], name: &str, value: &str) -> Option<::hmac::Hmac<::sha2::Sha256>> {
    use ::hmac::Mac;
    let mut mac = ::hmac::Hmac::<::sha2::Sha256>::new_from_slice(secret).ok()?;
    mac.update(name.as_bytes());
    mac.update(b"=");
    mac.update(value.as_bytes());
    Some(mac)
}

fn axum_dsl_cookie_sign(secret: &[u8], name: &str, value: &str) -> String {
    use ::base64::Engine;
    use ::hmac::Mac;
    let url = ::base64::engine::general_purpose::URL_SAFE_NO_PAD;
    let tag = match axum_dsl_cookie_mac(secret, name, value) {
        Some(mac) => mac.finalize().into_bytes(),
        None => return String::new(),
    };
    format!("{}.{}", url.encode(value), url.encode(tag))
}

fn axum_dsl_cookie_verify(secret: &[u8], name: &str, signed: &str) -> Option<String> {
    use ::base64::Engine;
    use ::hmac::Mac;
    let url = ::base64::engine::general_purpose::URL_SAFE_NO_PAD;
    let (value_part, tag_part) = signed.split_once('.')?;
    let value = String::from_utf8(url.decode(value_part).ok()?).ok()?;
    let tag = url.decode(tag_part).ok()?;
    axum_dsl_cookie_mac(secret, name, &value)?.verify_slice(&tag).ok()?;
    Some(value)
}

fn axum_dsl_cookie(headers: &::axum::http::HeaderMap, name: &str) -> Option<String> {
    for line in headers.get_all(::axum::http::header::COOKIE) {
        let Ok(line) = line.to_str() else { continue };
        for pair in line.split(';') {
            if let Some((key, signed)) = pair.trim().split_once('=') {
                if key == name {
                    if let Some(value) = axum_dsl_cookie_verify(axum_dsl_cookie_key(), name, signed) {
                        return Some(value);
                    }
                }
            }
        }
    }
    None
}

fn axum_dsl_set_cookie(name: &str, value: &str, http_only: bool, same_site: &str, secure: bool, max_age: Option<i64>) -> String {
    let mut line = format!("{}={}; Path=/", name, axum_dsl_cookie_sign(axum_dsl_cookie_key(), name, value));
    if let Some(seconds) = max_age {
        line.push_str(&format!("; Max-Age={seconds}"));
    }
    line.push_str(&format!("; SameSite={same_site}"));
    if http_only {
        line.push_str("; HttpOnly");
    }
    if secure {
        line.push_str("; Secure");
    }
    line
}

fn axum_dsl_delete_cookie(name: &str) -> String {
    format!("{name}=; Path=/; Max-Age=0")
}

fn axum_dsl_apply_cookies(response: &mut ::axum::response::Response, cookies: &[String]) {
    for cookie in cookies {
        if let Ok(value) = ::axum::http::HeaderValue::from_str(cookie) {
            response.headers_mut().append(::axum::http::header::SET_COOKIE, value);
        }
    }
}

// sessions runtime (random_token, request_ip, user_agent, Bcrypt, the current and filter helpers): written by the compiler
fn axum_dsl_random_token() -> String {
    use ::rand::Rng;
    const ALPHABET: &[u8] = b"123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
    let mut rng = ::rand::rng();
    (0..24)
        .map(|_| char::from(ALPHABET.get(rng.random_range(0..ALPHABET.len())).copied().unwrap_or(b'1')))
        .collect()
}

fn axum_dsl_request_ip(_headers: &::axum::http::HeaderMap, peer: Option<::std::net::SocketAddr>) -> String {
    peer.map(|addr| addr.ip().to_string()).unwrap_or_default()
}

fn axum_dsl_user_agent(headers: &::axum::http::HeaderMap) -> String {
    headers
        .get(::axum::http::header::USER_AGENT)
        .and_then(|value| value.to_str().ok())
        .unwrap_or_default()
        .to_string()
}

async fn axum_dsl_bcrypt_verify(plain: String, digest: String) -> bool {
    ::tokio::task::spawn_blocking(move || ::bcrypt::verify(plain, &digest).unwrap_or(false))
        .await
        .unwrap_or(false)
}

async fn axum_dsl_bcrypt_hash(plain: String) -> Result<String, String> {
    ::tokio::task::spawn_blocking(move || ::bcrypt::hash(plain, 12).map_err(|e| format!("error: Bcrypt.hash failed: {e}")))
        .await
        .map_err(|e| format!("error: Bcrypt.hash failed: {e}"))?
}

async fn axum_dsl_fetch_metadata(request: ::axum::extract::Request, next: ::axum::middleware::Next) -> ::axum::response::Response {
    let method = request.method();
    let reads = *method == ::axum::http::Method::GET || *method == ::axum::http::Method::HEAD || *method == ::axum::http::Method::OPTIONS;
    let cross_site = matches!(
        request.headers().get("sec-fetch-site"),
        Some(site) if site.as_bytes() != b"same-origin" && site.as_bytes() != b"none"
    );
    if !reads && cross_site {
        let mut refused = ::axum::response::IntoResponse::into_response("cross-site request refused");
        *refused.status_mut() = ::axum::http::StatusCode::FORBIDDEN;
        return refused;
    }
    next.run(request).await
}

// use_layer :rate_limit: one fixed window of requests per client address: written by the compiler
const AXUM_DSL_RATE_LIMIT_PER: u64 = 60;
const AXUM_DSL_RATE_LIMIT_BURST: u32 = 25;
const AXUM_DSL_RATE_LIMIT_PATH: &str = "/session";
static AXUM_DSL_RATE_LIMIT: ::std::sync::OnceLock<::std::sync::Mutex<::std::collections::HashMap<String, (u64, u32)>>> =
    ::std::sync::OnceLock::new();

async fn axum_dsl_rate_limit(request: ::axum::extract::Request, next: ::axum::middleware::Next) -> ::axum::response::Response {
    if !AXUM_DSL_RATE_LIMIT_PATH.is_empty() && request.uri().path() != AXUM_DSL_RATE_LIMIT_PATH {
        return next.run(request).await;
    }
    let peer = request.extensions().get::<::axum::extract::ConnectInfo<::std::net::SocketAddr>>().map(|info| info.0);
    let client = axum_dsl_request_ip(request.headers(), peer);
    let now = ::std::time::SystemTime::now()
        .duration_since(::std::time::UNIX_EPOCH)
        .map(|elapsed| elapsed.as_secs())
        .unwrap_or(0);
    let window = now / AXUM_DSL_RATE_LIMIT_PER;
    let over = {
        let cells = AXUM_DSL_RATE_LIMIT.get_or_init(|| ::std::sync::Mutex::new(::std::collections::HashMap::new()));
        let mut counts = match cells.lock() {
            Ok(guard) => guard,
            Err(poisoned) => poisoned.into_inner(),
        };
        let entry = counts.entry(client).or_insert((window, 0));
        if entry.0 != window {
            *entry = (window, 0);
        }
        entry.1 = entry.1.saturating_add(1);
        entry.1 > AXUM_DSL_RATE_LIMIT_BURST
    };
    if over {
        let mut refused = ::axum::response::IntoResponse::into_response("rate limit exceeded");
        *refused.status_mut() = ::axum::http::StatusCode::TOO_MANY_REQUESTS;
        return refused;
    }
    next.run(request).await
}

// the per-request values of `current`: each is computed on its first read and kept for the request: written by the compiler
#[derive(Default)]
struct AxumDslCurrents {
    user: ::tokio::sync::OnceCell<Option<User>>,
}

async fn axum_dsl_current_scope(mut request: ::axum::extract::Request, next: ::axum::middleware::Next) -> ::axum::response::Response {
    request.extensions_mut().insert(::std::sync::Arc::new(AxumDslCurrents::default()));
    next.run(request).await
}

async fn axum_dsl_current_user(__headers: &::axum::http::HeaderMap, __peer: Option<::std::net::SocketAddr>, __currents: &AxumDslCurrents) -> Result<Option<User>, String> {
    let token = axum_dsl_cookie(&__headers, "session_token");
    Ok(match token { None => { None }, Some(token) => { query_user_for_session(token.clone()).await? } })
}

fn internal_error(message: &str) -> ::axum::response::Response {
    let mut response = ::axum::response::IntoResponse::into_response(message.to_string());
    *response.status_mut() = ::axum::http::StatusCode::INTERNAL_SERVER_ERROR;
    response
}

fn error_response(message: &str) -> ::axum::response::Response {
    internal_error(message)
}

